// Simulate robot subsequence timeline
simulate[<=700]{Coffee_Delivery_robot1_def.s1_start, Coffee_Delivery_robot1_def.s1_end, Coffee_Delivery_robot1_def.s2_start, Coffee_Delivery_robot1_def.s2_end, Coffee_Delivery_robot1_def.s3_start, Coffee_Delivery_robot1_def.s3_end, Coffee_Delivery_robot1_def.s4_start, Coffee_Delivery_robot1_def.s4_end, Coffee_Delivery.end}

// Simulate employee subsequence timeline
simulate[<=700]{Coffee_Delivery_employee_def.s1_start, Coffee_Delivery_employee_def.s1_end, Coffee_Delivery_employee_def.s4_start, Coffee_Delivery_employee_def.s4_idle, Coffee_Delivery.end}

// Check if the whole pattern ends within 700 time units
Pr[<=700] (<> Coffee_Delivery.end)

// Check the position of all agents in the pattern for 700 time units
simulate[<=700]{humanPositionX[0], humanPositionY[0], robPositionX[0], robPositionY[0], batteryCharge[0], Coffee_Delivery.end}

// Check quantity of each item for each robot
simulate[<=700]{robot_inventory[0][0], Coffee_Delivery.end*2}

// Plot the position of each location in the pattern
simulate[<=700]{coffee_room[0], coffee_room[1], office001[0], office001[1]}

// Simulate robot idle flags
simulate[<=700]{rm_1.idle, rf_1.idle, rp_1.idle, rd_1.idle}

// Check that at least one robot is not idle
Pr[<=700](<> !rm_1.idle || !rf_1.idle || !rp_1.idle || !rd_1.idle)

// When pattern ends, all robots must be idle
Pr[<=700]([] (Coffee_Delivery.end imply (rm_1.idle && rf_1.idle && rp_1.idle && rd_1.idle)))

// Check if robot reaches Office (within 30 units)
Pr[<=700] (<> pow(robPositionX[0] - office001[0], 2) + pow(robPositionY[0] - office001[1], 2) <= 900)

// Check if robot reaches CoffeeMachine (within 30 units)
Pr[<=700] (<> pow(robPositionX[0] - coffee_room[0], 2) + pow(robPositionY[0] - coffee_room[1], 2) <= 900)

// Check if human enters an invalid position
Pr[<=700] (<> !isValidPosition(humanPositionX[0], humanPositionY[0]))

// Check if robot enters an invalid position
Pr[<=700] (<> !isValidPosition(robPositionX[0], robPositionY[0]))

// Check if pattern is executed more than once
Pr[<=700] (<> currP > 2)
